# -*- coding: utf-8 -*-
# patch_iskra_soul.py
# ============================================================
# ПАТЧ: душа города в Искре + петля обучения.
# Спринт 45 · 2026-06-16
#
# Аудит grondheim_memory.py: все функции принимают dept — система
# памяти НЕ захардкожена под медиацеха, работает для trading.
# Искра найдётся по registry_id=A01_ISKRA. ДНК полная (static+dynamic).
#
# Что подключено в iskra_live.py:
#   1. format_soul_for_agent("A01_ISKRA", dept="trading") в ПРОГОН и в ЧАТ —
#      Искра думает со своим настроением, ДНК, резонансом, памятью.
#      Усталость/streak/ссора на прогулке окрашивают её ГОЛОС.
#   2. ГРАНИЦА в промте: душа красит narrative (голос), но signal —
#      факт движка. Злость не рождает дивергенцию, усталость не прячет.
#   3. sync_to_dna — ПЕТЛЯ ОБУЧЕНИЯ через точность отражения:
#      DETECTED→CONFIRMED = good_work (streak↑, Light↑, Stress↓)
#      DETECTED→NOT_FOUND = bad_work (streak↓, Stress↑)
#      Искра учится не на деньгах (это трейдеры), а на ТОЧНОСТИ —
#      путь датчика к мастерству.
#
# Душа/память грузятся в try/except — если не доступны, Искра
# работает без них, не падает.
#
# Бэкап (.bak). Запуск из корня репо: python patch_iskra_soul.py
# ============================================================
import base64, os, shutil
FILES = {
    "studio/modules/trading/iskra_live.py": ""
}
def main():
    root = os.getcwd()
    print("=== ПАТЧ: душа города в Искре + петля обучения ===")
    for dest, b64 in FILES.items():
        path = os.path.join(root, dest.replace("/", os.sep))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        if os.path.exists(path):
            shutil.copy2(path, path + ".bak")
            print(f"  [BAK] {dest}.bak")
        open(path, "wb").write(base64.b64decode(b64))
        print(f"  [OK ] {dest}")
    print("=== ГОТОВО ===")
    print("Прогони РЫНОК: Искра теперь думает с настроением.")
    print("Спроси её в чате про самочувствие — она знает свой Stress,")
    print("streak, тягу к окну. Но рынок отражает честно (граница голос/сигнал).")
    print("Со временем точные сигналы поднимут streak — она растёт в мастерстве.")
if __name__ == "__main__":
    main()
